program = '''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if g[r][c] == 0}
    components = []
    while unseen:
        seed = unseen.pop()
        component = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    component.add(p)
                    stack.append(p)
        components.append(component)
    objects = []
    for component in components:
        rs = [r for r, c in component]
        cs = [c for r, c in component]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        payload = {(r,c): g[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1) if g[r][c] in (0,9)}
        if r1-r0 > c1-c0:
            dr = h-3-r0 if sum(g[r0][c] == 0 for c in range(c0,c1+1)) >= 2 else -r0
            dc = 0
        else:
            dr = 0
            dc = w-3-c0 if sum(g[r][c0] == 0 for r in range(r0,r1+1)) >= 2 else -c0
        objects.append((payload,dr,dc))
    for payload, _, _ in objects:
        for r, c in payload:
            g[r][c] = 7
    for payload, dr, dc in objects:
        for (r,c), value in payload.items():
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                g[nr][nc] = value
    return g
'''
